package store

import (
	"context"
	"errors"

	"warden/internal/model"
)

// ErrAuditWrite intentionally carries no driver error or SQL parameter data.
var ErrAuditWrite = errors.New("audit persistence failed")

// AppendAudit persists an event already classified/bounded by the audit recorder.
// CreatedAt is generated by the server;
// caller-supplied values are ignored.
func (s *Store) AppendAudit(ctx context.Context, e model.AuditEvent) error {
	_, err := s.db.ExecContext(ctx, `
		INSERT INTO audit_events
			(operation, resource_type, resource_id, source, result, error, metadata, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		e.Operation, e.ResourceType, e.ResourceID, e.Source, e.Result, e.Error,
		e.Metadata, nowUTC())
	if err != nil {
		return ErrAuditWrite
	}
	return nil
}
